class Solution {
    fun queensAttacktheKing(queens:Array<IntArray>,king:IntArray):List<List<Int>>{
        val occupied=Array(8){
            BooleanArray(8)
        };
        for(queen in queens)occupied[queen[0]][queen[1]]=true;
        val directions=arrayOf(intArrayOf(-1,-1),intArrayOf(-1,0),intArrayOf(-1,1),intArrayOf(0,-1),intArrayOf(0,1),intArrayOf(1,-1),intArrayOf(1,0),intArrayOf(1,1));
        val answer=mutableListOf<List<Int>>();
        for(direction in directions){
            var r=king[0]+direction[0];
            var c=king[1]+direction[1];
            while(r in 0..7&&c in 0..7){
                if(occupied[r][c]){
                    answer.add(listOf(r,c));
                    break
                };
                r+=direction[0];
                c+=direction[1]
            }
        };
        return answer
    }
}

